INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('760cb817-3e98-59c4-8c17-64ba81c98422', '3a5b7392-db09-57c4-bb31-b7e9274ceeb6', 'shipment_type', 'Shipment Type', 'The shipment type of the shipment: a value the business records on it. Entered or maintained when a shipment is created or changed; shown on its form and available to search and reports. Read together with the shipment''s other fields and its relationships; it is not meaningful on its own. Required: a shipment cannot be understood without its shipment type. The shipment type of the shipment is inbound; set it when that is what the business means for this record. The shipment type of the shipment is outbound; set it when that is what the business means for this record. The shipment type of the shipment is transfer; set it when that is what the business means for this record. The shipment type of the shipment is return; set it when that is what the business means for this record.', 1026, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 30, 'U', TRUE, 'system', 'system', NOW(), NOW())
