INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('7c677c7b-24d0-5b53-b57d-4b3b2a477565', '3a5b7392-db09-57c4-bb31-b7e9274ceeb6', 'status', 'Status', 'Operational execution state of the shipment. Controls booking, dispatch, tracking, delivery, exception and cancellation actions. Status is not inventory status and does not itself prove customer acceptance or invoice payment. Drives permitted logistics transitions and downstream fulfillment/movement workflows. The status of the shipment is planned; set it when that is what the business means for this record. The status of the shipment is booked; set it when that is what the business means for this record. The status of the shipment is in transit; set it when that is what the business means for this record. The status of the shipment is delivered; set it when that is what the business means for this record. The status of the shipment is cancelled; set it when that is what the business means for this record. The status of the shipment is exception; set it when that is what the business means for this record.', 1027, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
