INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b85705b7-c926-52ed-ab7c-c03870783d2b', '0777a7de-46ff-5aa0-87bf-8a6341357c18', 'status', 'Status', 'The lifecycle state of the record. It controls which business actions are normally permitted and how the record is treated by related processes. Used when creating, reviewing, searching, validating, reporting on, or integrating Vehicle records, where applicable. Its meaning is specific to Vehicle; it must be interpreted with the entity''s relationships, lifecycle, and business rules rather than as an isolated technical value. Represents the active state or classification in the context of Vehicle. Represents the maintenance state or classification in the context of Vehicle. Represents the out of service state or classification in the context of Vehicle. Represents the retired state or classification in the context of Vehicle. Required because the business model cannot reliably interpret the record for its declared purpose without this value.', 1036, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 50, 'U', TRUE, 'system', 'system', NOW(), NOW())
