INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('b39c0f02-668a-558c-8a75-334d54c5822a', 'ce5151d4-2613-5066-9cb3-90bc1d549248', 'status', 'Status', 'Order-level lifecycle state controlling commercial and fulfillment permissions. Drives confirmation, allocation, fulfillment, shipment readiness and cancellation. Summarizes downstream evidence; it is not an independent source of fulfillment quantity. Status transitions are validated against line, reservation, shipment and fulfillment evidence. The status of the sales order is draft; set it when that is what the business means for this record. The status of the sales order is confirmed; set it when that is what the business means for this record. The status of the sales order is allocated; set it when that is what the business means for this record. The status of the sales order is partially fulfilled; set it when that is what the business means for this record. The status of the sales order is fulfilled; set it when that is what the business means for this record. The status of the sales order is cancelled; set it when that is what the business means for this record.', 1025, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 40, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
