INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('90b6fca7-1154-5d46-80c3-ff9ef59fa5af', '43705ff7-e568-5245-9edd-8c2cff73aa2f', 'b39c0f02-668a-558c-8a75-334d54c5822a', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Status', 'Order-level lifecycle state controlling commercial and fulfillment permissions. Drives confirmation, allocation, fulfillment, shipment readiness and cancellation. Summarizes downstream evidence; it is not an independent source of fulfillment quantity. Status transitions are validated against line, reservation, shipment and fulfillment evidence. The status of the sales order is draft; set it when that is what the business means for this record. The status of the sales order is confirmed; set it when that is what the business means for this record. The status of the sales order is allocated; set it when that is what the business means for this record. The status of the sales order is partially fulfilled; set it when that is what the business means for this record. The status of the sales order is fulfilled; set it when that is what the business means for this record. The status of the sales order is cancelled; set it when that is what the business means for this record. Required — the record cannot be saved while this is empty.', 40, 40, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
