INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('c4b29932-a503-56c2-bbbe-33d9119d6656', 'Delivery', 'Maintain Delivery records', 'Create, find and maintain Delivery records. The list shows every Delivery you have access to — select a row to open it, or use New to add one. Each row is a single Delivery, described by 3 fields.

Id is unique: no two Delivery records may share the same value, and a save that would duplicate one is rejected. Shipment must be filled in before the record can be saved.

Every Delivery points at Shipment. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Delivery then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Delivery with no rules or workflows attached is marked Final immediately.', 'truck', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e21901ab-e1d2-55d4-9e6d-f435d9a858cc', 'bus_delivery', 'Delivery', 'A governed delivery execution record proving handoff of shipped goods to an eligible destination or recipient. Provide canonical implementation-neutral semantics for Delivery across enterprise applications. A governed delivery execution record proving handoff of shipped goods to an eligible destination or recipient. Used in CRM, sales, fulfillment, logistics, reporting, integration, or audit processes where this concept applies. Connects to canonical parties, commercial transactions, logistics execution, and downstream evidence without replacing their authoritative records. Created and progressed through governed business workflow; completed history is retained and corrections are explicit. Commercial management, fulfillment, logistics execution, reconciliation, reporting, and audit. Enterprise sales and supply-chain operations.', 'truck', 'A', FALSE, FALSE, FALSE, TRUE, 'c4b29932-a503-56c2-bbbe-33d9119d6656', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
