INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('69f74ba9-2ff2-5a60-bd2d-b9d3704202fd', 'Freight Charge', 'Maintain Freight Charge records', 'Create, find and maintain Freight Charge records. The list shows every Freight Charge you have access to — select a row to open it, or use New to add one. Each row is a single Freight Charge, described by 3 fields.

Id is unique: no two Freight Charge records may share the same value, and a save that would duplicate one is rejected.

Every Freight Charge points at Shipment. Choose the linked record from the lookup on those fields rather than typing an identifier.

Every save starts as a Draft. The business rules and workflows attached to Freight Charge then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Freight Charge with no rules or workflows attached is marked Final immediately.', 'table', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5019675d-3bcb-584c-88df-d9062ec728bf', 'bus_freight_charge', 'Freight Charge', 'A governed monetary charge for transportation or logistics services attributable to a shipment, consignment, load, or carrier service. Provide canonical implementation-neutral semantics for FreightCharge across enterprise applications. A governed monetary charge for transportation or logistics services attributable to a shipment, consignment, load, or carrier service. Used in CRM, sales, fulfillment, logistics, reporting, integration, or audit processes where this concept applies. Connects to canonical parties, commercial transactions, logistics execution, and downstream evidence without replacing their authoritative records. Created and progressed through governed business workflow; completed history is retained and corrections are explicit. Commercial management, fulfillment, logistics execution, reconciliation, reporting, and audit. Enterprise sales and supply-chain operations.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, '69f74ba9-2ff2-5a60-bd2d-b9d3704202fd', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
