INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5ad6d91b-1814-5431-9a77-90ba35b57912', 'Route', 'Maintain Route records', 'Create, find and maintain Route records. The list shows every Route you have access to — select a row to open it, or use New to add one. Each row is a single Route, described by 2 fields.

Id is unique: no two Route records may share the same value, and a save that would duplicate one is rejected.

Every save starts as a Draft. The business rules and workflows attached to Route then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Route with no rules or workflows attached is marked Final immediately.', 'route', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('d3dcd461-8646-5172-b4fc-7a04d44fc40d', 'bus_route', 'Route', 'A governed planned path or sequence of transport stops/legs used for shipment, fleet, or logistics execution. Provide canonical implementation-neutral semantics for Route across enterprise applications. A governed planned path or sequence of transport stops/legs used for shipment, fleet, or logistics execution. Used in CRM, sales, fulfillment, logistics, reporting, integration, or audit processes where this concept applies. Connects to canonical parties, commercial transactions, logistics execution, and downstream evidence without replacing their authoritative records. Created and progressed through governed business workflow; completed history is retained and corrections are explicit. Commercial management, fulfillment, logistics execution, reconciliation, reporting, and audit. Enterprise sales and supply-chain operations.', 'route', 'A', FALSE, FALSE, FALSE, TRUE, '5ad6d91b-1814-5431-9a77-90ba35b57912', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
