INSERT INTO sys_window (sys_window_id, name, description, help, icon, window_type, is_sales_transaction, is_default, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('ad63c116-34b0-5ac0-a2cf-2a23b530fbcf', 'Message', 'Maintain Message records', 'Create, find and maintain Message records. The list shows every Message you have access to — select a row to open it, or use New to add one. Each row is a single Message, described by 2 fields.

Id is unique: no two Message records may share the same value, and a save that would duplicate one is rejected.

Delivery Attempt refers back to Message, so what you change here can affect that record.

Every save starts as a Draft. The business rules and workflows attached to Message then run together in a single transaction: if all of them succeed the record becomes Final; if any of them fails, nothing they changed is kept — the record stays Draft and the reason is written onto it so you can fix the cause and retry. A Message with no rules or workflows attached is marked Final immediately.', 'table', 'M', FALSE, TRUE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_table (sys_table_id, table_name, name, description, icon, access_level, is_view, is_document, is_high_volume, is_changelog, sys_window_id, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('5b64908f-7725-52bb-ac5f-90b2861bdcd2', 'bus_message', 'Message', 'A governed integration message envelope preserving payload identity, direction, correlation, processing state, and delivery evidence. Provide canonical implementation-neutral integration semantics for Message. A governed integration message envelope preserving payload identity, direction, correlation, processing state, and delivery evidence. Used for event publication, message exchange, delivery, retry, reconciliation, integration operations, and audit. Carries or routes evidence derived from authoritative domain transactions without replacing those source records. Created and processed through governed integration states; attempts and finalized evidence are retained. Event publication, messaging, endpoint delivery, retry, dead-letter handling, reconciliation, and audit. Enterprise application integration and event-driven workflows.', 'table', 'A', FALSE, FALSE, FALSE, TRUE, 'ad63c116-34b0-5ac0-a2cf-2a23b530fbcf', 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
