INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('790bfa8c-c498-5492-a284-2f37af30d3d6', '825c265a-aa97-5925-ab0f-de022f62a39b', 'price_source', 'Price Source', 'The price source of the sales order line: a value the business records on it. Entered or maintained when a sales order line is created or changed; shown on its form and available to search and reports. Read together with the sales order line''s other fields and its relationships; it is not meaningful on its own. The price source of the sales order line is price list; set it when that is what the business means for this record. The price source of the sales order line is contract; set it when that is what the business means for this record. The price source of the sales order line is customer agreement; set it when that is what the business means for this record. The price source of the sales order line is quotation; set it when that is what the business means for this record. The price source of the sales order line is manual; set it when that is what the business means for this record. The price source of the sales order line is promotion; set it when that is what the business means for this record. The price source of the sales order line is other; set it when that is what the business means for this record.', 1024, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 100, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
