ON CONFLICT DO NOTHING;
INSERT INTO sys_column (sys_column_id, sys_table_id, column_name, name, description, sys_reference_id, field_length, default_value, is_key, is_parent, is_mandatory, is_updateable, is_identifier, is_selection_column, is_translated, is_encrypted, is_allow_logging, is_allow_copy, seq_no, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('79e110b5-a0a2-5475-8db0-d48625d3d27e', '825c265a-aa97-5925-ab0f-de022f62a39b', 'unit_of_measure_id', 'Unit Of Measure', 'Links a sales order line to unit of measure, the unit of measure it relates to. Chosen from the existing unit of measure records when the sales order line is created or edited. A sales order line has at most one unit of measure in this role. Lets the sales order line be found from, and reported with, its unit of measure.', 19, NULL, NULL, FALSE, FALSE, FALSE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 120, 'U', TRUE, 'system', 'system', NOW(), NOW())
