VALUES ('90b45c6b-d34f-59ca-8b1a-02edf987c6ad', '825c265a-aa97-5925-ab0f-de022f62a39b', 'product_id', 'Product', 'Links a sales order line to product, the product it relates to. Chosen from the existing product records when the sales order line is created or edited. A sales order line has exactly one product in this role. Lets the sales order line be found from, and reported with, its product.', 19, NULL, NULL, FALSE, FALSE, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, TRUE, TRUE, 140, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
