VALUES ('f28c7a3d-4fb7-51d3-b4db-f3389083ed99', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', '021f5e2a-9113-5671-babf-508b80b86c92', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Quantity Allocated', 'The quantity allocated of the sales order line: a number the business records on it. Entered or maintained when a sales order line is created or changed; shown on its form and available to search and reports. Read together with the sales order line''s other fields and its relationships; it is not meaningful on its own. Required: a sales order line cannot be understood without its quantity allocated. Required — the record cannot be saved while this is empty.', 50, 50, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f68bea8d-ac24-5b57-a00a-132ea3411d68', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', '01740e2d-6c42-569f-a0f0-14229607f87a', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Unit Price', 'Agreed transaction-time price per unit including currency. Order valuation, invoicing, margin, credit and reconciliation. Must align with SalesOrder currency and UnitOfMeasure pricing basis. Authoritative commercial price for downstream billing unless controlled repricing occurs. Required — the record cannot be saved while this is empty.', 60, 60, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('547c8a5b-bfaa-502f-858c-a77a63bed284', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', 'af8b7ebb-df0f-577e-9f6f-b415143a18fb', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Discount Amount', 'Approved transaction-time discount amount. Reconciles net commercial value and invoice calculations. Currency must match order pricing currency. Preserves the concession actually granted rather than relying on current DiscountRule.', 70, 70, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('292d6ba6-41e9-5b30-ae9d-2267a30b1b9a', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', '551b3bbd-c4bd-59f1-bb34-c9877dbaa15e', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Tax Amount', 'Tax determined for the order line when tax is calculated at order stage. Supports order and invoice reconciliation. Determination may depend on Product, Customer, address, location, date and TaxRule. Preserves tax evidence when the order commits to a tax amount.', 80, 80, TRUE, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6779277e-1b4c-5dd9-91af-8eae6e093479', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', '28c1603a-4681-5f71-82d8-c61c458d06a0', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Line Amount', 'Calculated commercial value of the line. Supports order totals, invoicing, credit and reporting. Must reconcile with pricing, discount, tax and rounding policy. Financial baseline for downstream billing and reconciliation. Required — the record cannot be saved while this is empty.', 90, 90, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('6b29f8d8-845d-5f12-a6e7-a1338ba0021c', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', '790bfa8c-c498-5492-a284-2f37af30d3d6', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Price Source', 'The price source of the sales order line: a value the business records on it. Entered or maintained when a sales order line is created or changed; shown on its form and available to search and reports. Read together with the sales order line''s other fields and its relationships; it is not meaningful on its own. The price source of the sales order line is price list; set it when that is what the business means for this record. The price source of the sales order line is contract; set it when that is what the business means for this record. The price source of the sales order line is customer agreement; set it when that is what the business means for this record. The price source of the sales order line is quotation; set it when that is what the business means for this record. The price source of the sales order line is manual; set it when that is what the business means for this record. The price source of the sales order line is promotion; set it when that is what the business means for this record. The price source of the sales order line is other; set it when that is what the business means for this record.', 100, 100, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('f3caf886-c6cf-5044-aceb-397d87ad3950', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', 'e7263cfe-92f7-525a-8274-f67d8dd8f23b', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Price Determined At', 'The price determined at of the sales order line: a point in time the business records on it. Entered or maintained when a sales order line is created or changed; shown on its form and available to search and reports. Read together with the sales order line''s other fields and its relationships; it is not meaningful on its own.', 110, 110, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('e096d335-c51d-5f51-9b80-5e179f6b12c9', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', '79e110b5-a0a2-5475-8db0-d48625d3d27e', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Unit Of Measure', 'Links a sales order line to unit of measure, the unit of measure it relates to. Chosen from the existing unit of measure records when the sales order line is created or edited. A sales order line has at most one unit of measure in this role. Lets the sales order line be found from, and reported with, its unit of measure.', 120, 120, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('9414b813-eec8-5c26-b1a4-5a32c1e0fd1a', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', '56aa9f4e-0b1f-59ca-bb43-373463bb73fa', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Sales Order', 'Links a sales order line to sales order, the sales order it relates to. Chosen from the existing sales order records when the sales order line is created or edited. A sales order line has exactly one sales order in this role. Lets the sales order line be found from, and reported with, its sales order. Required — the record cannot be saved while this is empty.', 130, 130, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
INSERT INTO sys_field (sys_field_id, sys_tab_id, sys_column_id, sys_field_group_id, name, help, seq_no, seq_no_grid, is_displayed, is_displayed_grid, is_read_only, is_encrypted, is_same_line, is_heading, is_field_only, entity_type, is_active, created_by, updated_by, created_at, updated_at)
VALUES ('0e774db1-f51d-563b-9983-0b50cf91c888', '80a2c3bc-6aa4-520f-b409-e7ec3e288439', '90b45c6b-d34f-59ca-8b1a-02edf987c6ad', 'd5a24911-ae2f-5311-9de6-d7282bb2dd1d', 'Product', 'Links a sales order line to product, the product it relates to. Chosen from the existing product records when the sales order line is created or edited. A sales order line has exactly one product in this role. Lets the sales order line be found from, and reported with, its product. Required — the record cannot be saved while this is empty.', 140, 140, TRUE, FALSE, FALSE, FALSE, FALSE, FALSE, FALSE, 'U', TRUE, 'system', 'system', NOW(), NOW())
ON CONFLICT DO NOTHING;
